def parts(n):return [s for s in re.findall('[a-z]+',unicodedata.normalize('NFKD',n).encode('ascii','ignore').decode().lower()) if s not in ['jr','sr','ii','iii','iv']]
def compatible(n,s):
 a,b=parts(n),parts(s)
 return len(a)==len(b) and all(x==y or len(x)==1 and y.startswith(x) or len(y)==1 and x.startswith(y) for x,y in zip(a,b))
